func sumSingle(s []int64) int64 {
	var total int64
	for i := range s {
		total += s[i]
	}
	return total
}

// An AI assistant's version with two accumulators.
func sumDual(s []int64) int64 {
	var a, b int64
	for i := 0; i+1 < len(s); i += 2 {
		a += s[i]
		b += s[i+1]
	}
	return a + b
}

fmt.Println(sumDual([]int64{1, 2, 3, 4, 5}))

// An AI assistant's version: "Four accumulators give the same sum, faster."
func sumF4(s []float64) float64 {
	var a, b, c, d float64
	for i := 0; i+3 < len(s); i += 4 {
		a += s[i]
		b += s[i+1]
		c += s[i+2]
		d += s[i+3]
	}
	return a + b + c + d
}
